package runners;

import io.cucumber.testng.AbstractTestNGCucumberTests;
import io.cucumber.testng.CucumberOptions;

/*
 * Executes only failed Cucumber Scenarios.
 *
 * Reads failed scenarios from:
 *
 * target/rerun.txt
 *
 * This runner is mainly used in CI/CD pipelines
 * to avoid executing the complete regression suite again.
 */

@CucumberOptions(

        // Reads failed scenarios generated by TestRunner.
        features = "@target/rerun.txt",

        glue = { "stepdefinitions", "hooks" },

        plugin = {
                "pretty",
                "html:target/retry-cucumber-report.html",
                "json:target/failed-cucumber.json"
        },

        monochrome = true,

        dryRun = false

)

public class FailedRunner extends AbstractTestNGCucumberTests {

}